        // PUSAT MATERI MODUL: PDF VIEWER + INDEXEDDB UPLOAD
        // =====================================================
        const DEFAULT_MATH_PDF_BASE64 = "";
        const MATERIAL_DB_NAME = 'EduSkyMaterialsDB';
        const MATERIAL_DB_VERSION = 1;
        const MATERIAL_STORE = 'materials';
        let materialDb = null;
        let moduleMaterials = [];
        let selectedModuleFiles = [];
        let activePdfMaterialId = null;
        let homePdfReader = null;
        let managerMode = localStorage.getItem('edusky_manager_mode') === 'teacher';

        const bundledMaterials = {
            100: [{
                id: 'bundled-math-pdf',
                moduleId: 100,
                name: 'Modul Matematika Kelas 2 — Penjumlahan dan Pengurangan.pdf',
                title: 'Modul Matematika Kelas 2',
                type: 'application/pdf',
                size: 132371,
                createdAt: '2026-07-12T00:00:00.000Z',
                isPrimary: true,
                isBundled: true,
                base64: DEFAULT_MATH_PDF_BASE64
            }]
        };

        function openMaterialDatabase() {
            return new Promise((resolve, reject) => {
                if(materialDb) return resolve(materialDb);
                if(!('indexedDB' in window)) return reject(new Error('Browser tidak mendukung IndexedDB.'));
                const request = indexedDB.open(MATERIAL_DB_NAME, MATERIAL_DB_VERSION);
                request.onupgradeneeded = event => {
                    const db = event.target.result;
                    if(!db.objectStoreNames.contains(MATERIAL_STORE)) {
                        const store = db.createObjectStore(MATERIAL_STORE, { keyPath: 'id' });
                        store.createIndex('moduleId', 'moduleId', { unique: false });
                    }
                };
                request.onsuccess = event => { materialDb = event.target.result; resolve(materialDb); };
                request.onerror = () => reject(request.error || new Error('Gagal membuka penyimpanan materi.'));
            });
        }

        async function getStoredMaterials(moduleId) {
            try {
                const db = await openMaterialDatabase();
                return await new Promise((resolve, reject) => {
                    const tx = db.transaction(MATERIAL_STORE, 'readonly');
                    const index = tx.objectStore(MATERIAL_STORE).index('moduleId');
                    const request = index.getAll(moduleId);
                    request.onsuccess = () => resolve(request.result || []);
                    request.onerror = () => reject(request.error);
                });
            } catch(error) {
                console.warn(error);
                return [];
            }
        }

        async function saveStoredMaterial(material) {
            const db = await openMaterialDatabase();
            return await new Promise((resolve, reject) => {
                const tx = db.transaction(MATERIAL_STORE, 'readwrite');
                tx.objectStore(MATERIAL_STORE).put(material);
                tx.oncomplete = () => resolve(material);
                tx.onerror = () => reject(tx.error);
            });
        }

        async function removeStoredMaterial(id) {
            const db = await openMaterialDatabase();
            return await new Promise((resolve, reject) => {
                const tx = db.transaction(MATERIAL_STORE, 'readwrite');
                tx.objectStore(MATERIAL_STORE).delete(id);
                tx.oncomplete = resolve;
                tx.onerror = () => reject(tx.error);
            });
        }

        function base64ToBlob(base64, type = 'application/octet-stream') {
            const bytes = atob(base64);
            const chunks = [];
            const chunkSize = 1024;
            for(let offset = 0; offset < bytes.length; offset += chunkSize) {
                const slice = bytes.slice(offset, offset + chunkSize);
                const numbers = new Array(slice.length);
                for(let i = 0; i < slice.length; i++) numbers[i] = slice.charCodeAt(i);
                chunks.push(new Uint8Array(numbers));
            }
            return new Blob(chunks, { type });
        }

        function getMaterialBlob(material) {
            if(material.blob instanceof Blob) return material.blob;
            if(material.base64) return base64ToBlob(material.base64, material.type);
            return null;
        }

        function formatFileSize(bytes) {
            if(!Number.isFinite(bytes) || bytes <= 0) return 'Ukuran tidak diketahui';
            const units = ['B', 'KB', 'MB', 'GB'];
            const i = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
            return `${(bytes / Math.pow(1024, i)).toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
        }

        function materialKind(type = '') {
            if(type === 'application/pdf') return 'pdf';
            if(type.startsWith('image/')) return 'image';
            return 'file';
        }

        function materialIcon(type = '') {
            const kind = materialKind(type);
            if(kind === 'pdf') return 'fa-file-pdf';
            if(kind === 'image') return 'fa-file-image';
            if(type.includes('word') || type.includes('document')) return 'fa-file-word';
            if(type.includes('presentation') || type.includes('powerpoint')) return 'fa-file-powerpoint';
            if(type.includes('sheet') || type.includes('excel')) return 'fa-file-excel';
            if(type.includes('zip')) return 'fa-file-zipper';
            return 'fa-file-lines';
        }

        async function loadModuleMaterials(moduleId) {
            const stored = await getStoredMaterials(moduleId);
            const hasStoredPrimaryPdf = stored.some(item => item.type === 'application/pdf' && item.isPrimary);
            const bundled = (bundledMaterials[moduleId] || []).map(item => ({
                ...item,
                isPrimary: item.type === 'application/pdf' ? (item.isPrimary && !hasStoredPrimaryPdf) : item.isPrimary
            }));
            moduleMaterials = [...bundled, ...stored].sort((a, b) => {
                if(Boolean(a.isPrimary) !== Boolean(b.isPrimary)) return a.isPrimary ? -1 : 1;
                return new Date(b.createdAt || 0) - new Date(a.createdAt || 0);
            });
            renderModuleMaterials();
            const preferred = moduleMaterials.find(item => item.type === 'application/pdf' && item.isPrimary)
                || moduleMaterials.find(item => item.type === 'application/pdf');
            if(preferred) showPdfMaterial(preferred.id);
            else clearPdfViewer();
        }

        function renderModuleMaterials() {
            const list = document.getElementById('module-material-list');
            const imageSection = document.getElementById('image-material-section');
            const imageGrid = document.getElementById('image-material-grid');
            if(!list || !imageGrid || !imageSection) return;

            if(moduleMaterials.length === 0) {
                list.innerHTML = '<div class="text-center text-muted" style="padding:25px 8px;"><i class="fas fa-folder-open" style="font-size:2rem; margin-bottom:8px;"></i><p>Belum ada file.</p></div>';
            } else {
                list.innerHTML = moduleMaterials.map(item => {
                    const kind = materialKind(item.type);
                    const title = escapeHtml(item.title || item.name);
                    const primary = item.isPrimary ? '<span class="badge badge-success" style="font-size:.58rem;">UTAMA</span>' : '';
                    const builtin = item.isBundled ? '<span class="badge badge-primary" style="font-size:.58rem;">BAWAAN</span>' : '';
                    let action = '';
                    if(kind === 'pdf') {
                        action += `<button class="material-mini-btn" onclick="showPdfMaterial('${item.id}')"><i class="fas fa-book-open"></i> Baca</button>`;
                        action += `<button class="material-mini-btn" onclick="downloadMaterial('${item.id}')"><i class="fas fa-download"></i> Unduh</button>`;
                    }
                    else action += `<button class="material-mini-btn" onclick="downloadMaterial('${item.id}')"><i class="fas fa-download"></i> Unduh</button>`;
                    if(managerMode && !item.isBundled) {
                        if(kind === 'pdf' && !item.isPrimary) action += `<button class="material-mini-btn" onclick="setPrimaryPdf('${item.id}')"><i class="fas fa-thumbtack"></i> Utama</button>`;
                        action += `<button class="material-mini-btn delete" onclick="deleteMaterial('${item.id}')"><i class="fas fa-trash"></i></button>`;
                    }
                    return `
                        <article class="material-item ${activePdfMaterialId === item.id ? 'active' : ''}" data-material-id="${item.id}">
                            <div class="material-type-icon ${kind}"><i class="fas ${materialIcon(item.type)}"></i></div>
                            <div style="min-width:0;">
                                <div class="material-item-name">${title}</div>
                                <div class="flex gap-2" style="align-items:center; flex-wrap:wrap;">${primary}${builtin}</div>
                                <div class="material-item-meta">${formatFileSize(item.size)} • ${kind === 'pdf' ? 'PDF' : (kind === 'image' ? 'Gambar' : 'Lampiran')}</div>
                                <div class="material-item-actions">${action}</div>
                            </div>
                        </article>`;
                }).join('');
            }

            const images = moduleMaterials.filter(item => materialKind(item.type) === 'image');
            imageSection.classList.toggle('hidden', images.length === 0);
            document.getElementById('image-material-count').innerText = `${images.length} gambar`;
            imageGrid.innerHTML = images.map(item => {
                const blob = getMaterialBlob(item);
                const url = blob ? URL.createObjectURL(blob) : '';
                return `
                    <figure class="image-material-card" onclick="openMaterialImage('${item.id}')">
                        <img src="${url}" alt="${escapeHtml(item.title || item.name)}">
                        ${managerMode && !item.isBundled ? `<button class="image-delete-btn" type="button" onclick="event.stopPropagation(); deleteMaterial('${item.id}')"><i class="fas fa-trash"></i></button>` : ''}
                        <figcaption>${escapeHtml(item.title || item.name)}</figcaption>
                    </figure>`;
            }).join('');
        }

        function escapeHtml(value = '') {
            return String(value).replace(/[&<>'"]/g, char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' })[char]);
        }

        async function showPdfMaterial(id) {
            const material = moduleMaterials.find(item => String(item.id) === String(id));
            if(!material || material.type !== 'application/pdf') return;
            const blob = getMaterialBlob(material);
            if(!blob) return showToast('File PDF tidak dapat dibaca.', 'error');
            activePdfMaterialId = material.id;
            const viewer = document.getElementById('module-pdf-viewer');
            const empty = document.getElementById('pdf-empty-state');
            viewer.classList.remove('hidden');
            empty.classList.add('hidden');
            document.getElementById('btn-download-pdf').hidden = false;
            document.getElementById('active-pdf-title').innerText = material.title || material.name;
            document.getElementById('active-pdf-meta').innerText = `${formatFileSize(material.size)} • Dibaca langsung tanpa keluar dari web`;
            renderModuleMaterials();

            try {
                const data = await blob.arrayBuffer();
                await homePdfReader.load(data);
            } catch(error) {
                console.error('PDF gagal ditampilkan:', error);
                showToast('PDF gagal ditampilkan. Periksa koneksi internet.', 'error');
            }
        }

        function clearPdfViewer() {
            activePdfMaterialId = null;
            const viewer = document.getElementById('module-pdf-viewer');
            homePdfReader?.clear();
            viewer.classList.add('hidden');
            document.getElementById('pdf-empty-state').classList.remove('hidden');
            document.getElementById('btn-download-pdf').hidden = true;
            document.getElementById('active-pdf-title').innerText = 'Belum ada PDF utama';
            document.getElementById('active-pdf-meta').innerText = 'Guru atau admin dapat mengunggah file PDF';
        }

        function reloadActivePdf() {
            if(!activePdfMaterialId) return showToast('Belum ada PDF yang dipilih.', 'warning');
            showPdfMaterial(activePdfMaterialId);
        }

        async function setPrimaryPdf(id) {
            if(!managerMode) return;
            const target = moduleMaterials.find(item => String(item.id) === String(id));
            if(!target || target.isBundled) return;
            const stored = await getStoredMaterials(activeModule.id);
            for(const item of stored) {
                item.isPrimary = String(item.id) === String(id);
                await saveStoredMaterial(item);
            }
            await loadModuleMaterials(activeModule.id);
            showToast('PDF utama berhasil diperbarui.', 'success');
        }

        async function deleteMaterial(id) {
            if(!managerMode || !activeModule) return;
            const item = moduleMaterials.find(x => String(x.id) === String(id));
            if(!item || item.isBundled) return;
            if(!confirm(`Hapus materi "${item.title || item.name}"?`)) return;
            await removeStoredMaterial(item.id);
            await loadModuleMaterials(activeModule.id);
            showToast('Materi berhasil dihapus.', 'success');
        }

        function downloadMaterial(id) {
            const item = moduleMaterials.find(x => String(x.id) === String(id));
            if(!item) return;
            const blob = getMaterialBlob(item);
            if(!blob) return showToast('File tidak dapat diunduh.', 'error');
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = item.name || item.title || 'materi';
            document.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(() => URL.revokeObjectURL(url), 1000);
        }

        function openMaterialImage(id) {
            const item = moduleMaterials.find(x => String(x.id) === String(id));
            if(!item) return;
            const blob = getMaterialBlob(item);
            if(!blob) return;
            const url = URL.createObjectURL(blob);
            const modal = document.getElementById('material-lightbox');
            const image = document.getElementById('material-lightbox-image');
            image.onload = () => URL.revokeObjectURL(url);
            image.src = url;
            image.alt = item.title || item.name;
            modal.classList.add('show');
        }

        function closeMaterialImage() {
            document.getElementById('material-lightbox').classList.remove('show');
            document.getElementById('material-lightbox-image').removeAttribute('src');
        }

        function updateManagerUI() {
            const indicator = document.getElementById('module-role-indicator');
            const button = document.getElementById('btn-toggle-manager-mode');
            const panel = document.getElementById('module-manager-panel');
            const moduleView = document.getElementById('module-detail-view');
            if(!indicator || !button || !panel) return;
            if(managerMode) {
                indicator.className = 'role-indicator manager';
                indicator.innerHTML = '<i class="fas fa-user-shield"></i> Mode Guru/Admin • dapat mengelola file';
                button.className = 'btn btn-success';
                button.innerHTML = '<i class="fas fa-unlock"></i> Pengelola Aktif';
                panel.classList.remove('hidden');
                moduleView.classList.add('manager-mode');
            } else {
                indicator.className = 'role-indicator';
                indicator.innerHTML = '<i class="fas fa-user-graduate"></i> Mode Siswa • hanya membaca materi';
                button.className = 'btn btn-outline';
                button.innerHTML = '<i class="fas fa-lock"></i> Mode Guru/Admin';
                panel.classList.add('hidden');
                moduleView.classList.remove('manager-mode');
            }
            if(moduleMaterials.length) renderModuleMaterials();
        }

        function toggleManagerMode() {
            if(managerMode) {
                managerMode = false;
                localStorage.removeItem('edusky_manager_mode');
                updateManagerUI();
                showToast('Kembali ke mode siswa.', 'success');
                return;
            }
            const code = prompt('Masukkan kode demo Guru/Admin:');
            if(code !== '1234') return showToast('Kode pengelola tidak sesuai.', 'error');
            managerMode = true;
            localStorage.setItem('edusky_manager_mode', 'teacher');
            updateManagerUI();
            showToast('Mode Guru/Admin aktif.', 'success');
        }

        function handleSelectedModuleFiles(files) {
            const allowedMax = 15 * 1024 * 1024;
            const incoming = Array.from(files || []).filter(file => {
                if(file.size > allowedMax) {
                    showToast(`${file.name} melebihi batas 15 MB.`, 'warning');
                    return false;
                }
                return true;
            });
            selectedModuleFiles = incoming;
            const container = document.getElementById('selected-module-files');
            container.innerHTML = incoming.map(file => `
                <div class="selected-file-chip">
                    <span><i class="fas ${materialIcon(file.type)}"></i> ${escapeHtml(file.name)}</span>
                    <strong>${formatFileSize(file.size)}</strong>
                </div>`).join('');
        }

        async function uploadSelectedModuleFiles() {
            if(!managerMode || !activeModule) return;
            if(selectedModuleFiles.length === 0) return showToast('Pilih file terlebih dahulu.', 'warning');
            const customTitle = document.getElementById('module-material-title').value.trim();
            const makePrimary = document.getElementById('module-set-primary').checked;
            const existingStored = await getStoredMaterials(activeModule.id);
            const hasPrimaryStored = existingStored.some(item => item.type === 'application/pdf' && item.isPrimary);
            let primaryAssigned = hasPrimaryStored;

            for(let index = 0; index < selectedModuleFiles.length; index++) {
                const file = selectedModuleFiles[index];
                const isPdf = file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf');
                const title = customTitle && selectedModuleFiles.length === 1
                    ? customTitle
                    : file.name.replace(/\.[^/.]+$/, '');
                const material = {
                    id: `material-${activeModule.id}-${Date.now()}-${index}-${Math.random().toString(16).slice(2)}`,
                    moduleId: activeModule.id,
                    name: file.name,
                    title,
                    type: isPdf ? 'application/pdf' : (file.type || 'application/octet-stream'),
                    size: file.size,
                    createdAt: new Date().toISOString(),
                    isPrimary: Boolean(isPdf && makePrimary && !primaryAssigned),
                    isBundled: false,
                    blob: file
                };
                if(material.isPrimary) primaryAssigned = true;
                await saveStoredMaterial(material);
            }

            selectedModuleFiles = [];
            document.getElementById('module-file-input').value = '';
            document.getElementById('module-material-title').value = '';
            document.getElementById('selected-module-files').innerHTML = '';
            await loadModuleMaterials(activeModule.id);
            showToast('Materi berhasil ditambahkan ke modul.', 'success');
        }

