        async function logout() {
            const confirmed = window.EduSkyLogoutConfirm
                ? await window.EduSkyLogoutConfirm.ask({
                    title: 'Yakin ingin keluar?',
                    message: 'Sesi belajarmu akan diakhiri. Kamu harus login kembali untuk membuka akun EduSky.',
                    confirmLabel: 'Ya, Logout'
                })
                : window.confirm('Apakah kamu yakin ingin logout?');

            if(!confirmed) return;

            const activeSession = currentUser;

            if(activeSession?.id && activeSession?.session_token) {
                try {
                    await fetch(`${HOME_SUPABASE_URL}/rest/v1/rpc/siswa_logout`, {
                        method: 'POST',
                        headers: {
                            apikey: HOME_SUPABASE_KEY,
                            Authorization: `Bearer ${HOME_SUPABASE_KEY}`,
                            'Content-Type': 'application/json'
                        },
                        body: JSON.stringify({
                            p_id: activeSession.id,
                            p_session_token: activeSession.session_token
                        })
                    });
                } catch(error) {
                    console.warn('Sesi Supabase tidak dapat dicabut:', error);
                }
            }

            localStorage.removeItem('edusky_user');
            currentUser = null;
            window.location.href = '../../index.html';
        }

