        function initEvents() {
            // Navbar Routing
            document.querySelectorAll('.nav-item').forEach(item => {
                item.addEventListener('click', function() {
                    if(this.hasAttribute('href')) return;

                    const target = this.getAttribute('data-target');
                    
                    // Update active class on nav
                    document.querySelectorAll('.nav-item').forEach(nav => nav.classList.remove('active'));
                    this.classList.add('active');
                    
                    // Show correct page
                    document.querySelectorAll('.page-content').forEach(page => page.classList.remove('active'));
                    document.getElementById('page-' + target).classList.add('active');
                    
                    // Jika ke halaman modul, pastikan kembali ke tampilan folder
                    if(target === 'modules') resetModuleView();
                    
                    // Close mobile menu if open
                    document.getElementById('main-nav-menu').classList.remove('open');
                });
            });

            // Mobile menu toggle
            document.getElementById('mobile-menu-toggle').addEventListener('click', () => {
                document.getElementById('main-nav-menu').classList.add('open');
                document.getElementById('mobile-menu-overlay').classList.add('open');
            });
            
            // Tutup menu via tombol silang
            document.getElementById('close-mobile-menu').addEventListener('click', () => {
                document.getElementById('main-nav-menu').classList.remove('open');
                document.getElementById('mobile-menu-overlay').classList.remove('open');
            });
            
            // Tutup menu via overlay / background luar
            document.getElementById('mobile-menu-overlay').addEventListener('click', () => {
                document.getElementById('main-nav-menu').classList.remove('open');
                document.getElementById('mobile-menu-overlay').classList.remove('open');
            });

            // Panel notifikasi bersama tersedia pada seluruh halaman siswa.
            document.getElementById('notif-toggle').addEventListener('click', () => {
                window.EduSkyNotifications?.open();
            });

            // Theme toggle
            document.getElementById('theme-toggle').addEventListener('change', function() {
                if(this.checked) {
                    document.body.setAttribute('data-theme', 'dark');
                    localStorage.setItem('edusky_theme', 'dark');
                } else {
                    document.body.removeAttribute('data-theme');
                    localStorage.setItem('edusky_theme', 'light');
                }
            });
            
            // Back to Subjects from Module List
            document.getElementById('btn-back-subjects').addEventListener('click', () => {
                resetModuleView();
            });

            // Back from module detail
            document.getElementById('btn-back-modules').addEventListener('click', () => {
                stopLessonVideo();
                resetMainYoutube();
                const mapel = activeModule ? activeModule.mapel : 'Matematika';
                document.getElementById('module-detail-view').classList.add('hidden');
                openSubject(mapel);
            });

            // Tab modul
            document.querySelectorAll('[data-mtab]').forEach(btn => {
                btn.addEventListener('click', function() {
                    const target = this.getAttribute('data-mtab');
                    document.querySelectorAll('[data-mtab]').forEach(b => b.classList.remove('active'));
                    document.querySelectorAll('#module-detail-view .tab-content').forEach(c => c.classList.remove('active'));
                    this.classList.add('active');
                    document.getElementById('mtab-' + target).classList.add('active');
                    if(target !== 'video') resetMainYoutube();
                });
            });

            // Tab kelas
            document.querySelectorAll('[data-ctab]').forEach(btn => {
                btn.addEventListener('click', function() {
                    const target = this.getAttribute('data-ctab');
                    document.querySelectorAll('[data-ctab]').forEach(b => b.classList.remove('active'));
                    document.querySelectorAll('#page-class > .tab-content').forEach(c => c.classList.remove('active'));
                    this.classList.add('active');
                    document.getElementById('ctab-' + target).classList.add('active');
                });
            });

            // Navigasi cerita gambar
            document.getElementById('btn-comic-next').addEventListener('click', () => {
                const lesson = getActiveLesson();
                if(!lesson || !lesson.comic) return;
                if(activeComicIndex < lesson.comic.length - 1) {
                    activeComicIndex++;
                    renderComic();
                }
            });
            document.getElementById('btn-comic-prev').addEventListener('click', () => {
                if(activeComicIndex > 0) {
                    activeComicIndex--;
                    renderComic();
                }
            });

            // Latihan
            document.getElementById('btn-submit-quiz').addEventListener('click', handleQuizAction);
            document.getElementById('btn-repeat-quiz').addEventListener('click', resetQuiz);

            // Video mini
            document.getElementById('video-play-button').addEventListener('click', startLessonVideo);
            document.getElementById('btn-mark-video').addEventListener('click', markLessonComplete);
            document.getElementById('btn-play-main-video').addEventListener('click', playMainVideo);

            // Pusat materi PDF dan upload guru/admin
            document.getElementById('btn-toggle-manager-mode').addEventListener('click', toggleManagerMode);
            document.getElementById('btn-exit-manager-mode').addEventListener('click', toggleManagerMode);
            document.getElementById('btn-reload-pdf').addEventListener('click', reloadActivePdf);
            document.getElementById('btn-download-pdf').addEventListener('click', () => {
                if(!activePdfMaterialId) return showToast('Belum ada PDF yang dipilih.', 'warning');
                downloadMaterial(activePdfMaterialId);
            });
            document.getElementById('btn-fullscreen-pdf').addEventListener('click', () => {
                const card = document.getElementById('pdf-reader-card');
                if(document.fullscreenElement) document.exitFullscreen();
                else if(card.requestFullscreen) card.requestFullscreen();
            });
            document.getElementById('module-file-input').addEventListener('change', event => handleSelectedModuleFiles(event.target.files));
            document.getElementById('btn-upload-module-files').addEventListener('click', uploadSelectedModuleFiles);
            document.getElementById('material-lightbox-close').addEventListener('click', closeMaterialImage);
            document.getElementById('material-lightbox').addEventListener('click', event => {
                if(event.target.id === 'material-lightbox') closeMaterialImage();
            });
            document.addEventListener('keydown', event => {
                if(event.key === 'Escape') closeMaterialImage();
            });

            const dropzone = document.getElementById('module-file-dropzone');
            ['dragenter', 'dragover'].forEach(name => dropzone.addEventListener(name, event => {
                event.preventDefault();
                dropzone.classList.add('dragging');
            }));
            ['dragleave', 'drop'].forEach(name => dropzone.addEventListener(name, event => {
                event.preventDefault();
                dropzone.classList.remove('dragging');
            }));
            dropzone.addEventListener('drop', event => handleSelectedModuleFiles(event.dataTransfer.files));
        }

        function updateTime() {
            const now = new Date();
            const timeEl = document.getElementById('current-time');
            const dateEl = document.getElementById('current-date');

            if(timeEl) {
                timeEl.innerText = now.toLocaleTimeString('id-ID', {
                    hour: '2-digit',
                    minute: '2-digit',
                    second: '2-digit'
                });
            }

            if(dateEl) {
                dateEl.innerText = now.toLocaleDateString('id-ID', {
                    weekday: 'long',
                    day: 'numeric',
                    month: 'long',
                    year: 'numeric'
                });
            }
        }

        function getGreeting() {
            const hour = new Date().getHours();
            if (hour < 12) return "Selamat Pagi";
            if (hour < 15) return "Selamat Siang";
            if (hour < 18) return "Selamat Sore";
            return "Selamat Malam";
        }

