        async function loadDashboardModules() {
            const container = document.getElementById('dash-modules-container');
            if(!container) return;

            container.innerHTML = '<p class="text-center text-muted" style="grid-column:1/-1; padding:28px;">Memuat modul dari admin...</p>';

            try {
                const response = await fetch(`${HOME_SUPABASE_URL}/rest/v1/rpc/list_modul_siswa`, {
                    method: 'POST',
                    headers: {
                        apikey: HOME_SUPABASE_KEY,
                        Authorization: `Bearer ${HOME_SUPABASE_KEY}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ p_search: '', p_subject: '', p_grade: '' })
                });

                const data = await response.json();
                if(!response.ok) throw new Error(data.message || 'Modul gagal dimuat.');
                renderDashboardModules(Array.isArray(data) ? data : []);
            } catch(error) {
                console.error('Modul dashboard gagal dimuat:', error);
                container.innerHTML = `
                    <div class="text-center" style="grid-column:1/-1; padding:28px;">
                        <p class="text-muted" style="margin-bottom:12px;">Modul admin belum dapat dimuat.</p>
                        <a class="btn btn-primary" href="../modul/index.html">Buka Katalog Modul</a>
                    </div>`;
            }
        }

